// Self-checking testbench for apb_gpio, instances at N = 8 and N = 32.
module apb_gpio_tb;

  reg         pclk;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  reg         cur;        // 0: N=8 instance, 1: N=32 instance
  reg  [7:0]  gpio_in8;
  reg  [31:0] gpio_in32;

  wire [31:0] prdata8;
  wire [31:0] prdata32;
  wire        pready8;
  wire        pready32;
  wire        pslverr8;
  wire        pslverr32;
  wire [7:0]  gpio_out8;
  wire [7:0]  gpio_oe8;
  wire [31:0] gpio_out32;
  wire [31:0] gpio_oe32;
  wire        irq8;
  wire        irq32;

  wire psel8  = psel & ~cur;
  wire psel32 = psel & cur;

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) u_n8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel8),
    .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
    .prdata(prdata8), .pready(pready8), .pslverr(pslverr8),
    .gpio_in(gpio_in8), .gpio_out(gpio_out8), .gpio_oe(gpio_oe8), .irq(irq8)
  );

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) u_n32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel32),
    .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
    .prdata(prdata32), .pready(pready32), .pslverr(pslverr32),
    .gpio_in(gpio_in32), .gpio_out(gpio_out32), .gpio_oe(gpio_oe32), .irq(irq32)
  );

  wire [31:0] prdata_w  = cur ? prdata32 : prdata8;
  wire        pready_w  = cur ? pready32 : pready8;
  wire        pslverr_w = cur ? pslverr32 : pslverr8;
  wire [31:0] prdata_o  = cur ? prdata8 : prdata32;
  wire        pslverr_o = cur ? pslverr8 : pslverr32;
  wire [31:0] out_w     = cur ? gpio_out32 : {24'd0, gpio_out8};
  wire [31:0] oe_w      = cur ? gpio_oe32 : {24'd0, gpio_oe8};
  wire        irq_w     = cur ? irq32 : irq8;
  wire [31:0] pins_mask = cur ? 32'hFFFF_FFFF : 32'h0000_00FF;

  localparam [7:0] A_DOUT = 8'h00;
  localparam [7:0] A_DIR  = 8'h04;
  localparam [7:0] A_DIN  = 8'h08;
  localparam [7:0] A_RISE = 8'h0C;
  localparam [7:0] A_FALL = 8'h10;
  localparam [7:0] A_HIGH = 8'h14;
  localparam [7:0] A_LOW  = 8'h18;
  localparam [7:0] A_EN   = 8'h1C;
  localparam [7:0] A_ST   = 8'h20;

  integer passed;
  integer failed;
  integer step;
  reg [8*64-1:0] nonce;

  initial pclk = 1'b0;
  always #5 pclk = ~pclk;

  // -------------------------------------------------------------------
  // Checks
  // -------------------------------------------------------------------
  task check32(input [31:0] got, input [31:0] exp);
    begin
      if (got !== exp) begin
        failed = failed + 1;
        $error("step %0d (N=%0d): got 0x%08h, expected 0x%08h", step, cur ? 32 : 8, got, exp);
      end else begin
        passed = passed + 1;
      end
    end
  endtask

  task check1(input got, input exp);
    begin
      if (got !== exp) begin
        failed = failed + 1;
        $error("step %0d (N=%0d): got %b, expected %b", step, cur ? 32 : 8, got, exp);
      end else begin
        passed = passed + 1;
      end
    end
  endtask

  // -------------------------------------------------------------------
  // Bus tasks: called at a falling edge, return at a falling edge, idle bus.
  // -------------------------------------------------------------------
  task xfer(input w, input [7:0] a, input [31:0] d, input [3:0] s,
            input [31:0] exp_rd, input e);
    begin
      psel    = 1'b1;
      penable = 1'b0;
      pwrite  = w;
      paddr   = a;
      pwdata  = d;
      pstrb   = w ? s : 4'b0000;
      #1;
      // Setup phase: outside access, prdata and pslverr are zero.
      check32(prdata_w, 32'd0);
      check1(pslverr_w, 1'b0);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      // Access phase.
      check1(pready_w, 1'b1);
      check1(pslverr_w, e);
      check32(prdata_w, w ? 32'd0 : exp_rd);
      // The unselected instance stays quiet.
      check32(prdata_o, 32'd0);
      check1(pslverr_o, 1'b0);
      @(negedge pclk);
      psel    = 1'b0;
      penable = 1'b0;
      pwrite  = 1'b0;
      pstrb   = 4'b0000;
    end
  endtask

  task wr(input [7:0] a, input [31:0] d, input [3:0] s, input e);
    begin
      xfer(1'b1, a, d, s, 32'd0, e);
    end
  endtask

  task rd(input [7:0] a, input [31:0] exp, input e);
    begin
      xfer(1'b0, a, 32'd0, 4'b0000, exp, e);
    end
  endtask

  task wrf(input [7:0] a, input [31:0] d);
    begin
      wr(a, d, 4'b1111, 1'b0);
    end
  endtask

  task rdx(input [7:0] a, input [31:0] exp);
    begin
      rd(a, exp, 1'b0);
    end
  endtask

  task set_pins(input [31:0] v);
    begin
      if (cur) gpio_in32 = v;
      else     gpio_in8  = v[7:0];
    end
  endtask

  task cycles(input integer n);
    begin
      repeat (n) @(negedge pclk);
    end
  endtask

  task do_reset;
    begin
      presetn = 1'b0;
      psel    = 1'b0;
      penable = 1'b0;
      @(negedge pclk);
      @(negedge pclk);
      check32({24'd0, gpio_out8}, 32'd0);
      check32({24'd0, gpio_oe8}, 32'd0);
      check1(irq8, 1'b0);
      check32(gpio_out32, 32'd0);
      check32(gpio_oe32, 32'd0);
      check1(irq32, 1'b0);
      presetn = 1'b1;
    end
  endtask

  task rw_lanes(input [7:0] a);
    begin
      wr(a, 32'hFFFF_FFFF, 4'b1111, 1'b0); rdx(a, pins_mask);
      wr(a, 32'h0000_0000, 4'b1110, 1'b0); rdx(a, pins_mask & 32'h0000_00FF);
      wr(a, 32'h0000_0000, 4'b0001, 1'b0); rdx(a, 32'h0000_0000);
      wr(a, 32'hA5C3_5AA5, 4'b0101, 1'b0); rdx(a, pins_mask & 32'h00C3_00A5);
      wr(a, 32'h3C96_E1FF, 4'b1010, 1'b0); rdx(a, pins_mask & 32'h3CC3_E1A5);
      wr(a, 32'hFFFF_FFFF, 4'b0000, 1'b0); rdx(a, pins_mask & 32'h3CC3_E1A5);
      wr(a, 32'h0000_0000, 4'b1111, 1'b0); rdx(a, 32'h0000_0000);
    end
  endtask

  // -------------------------------------------------------------------
  // Tests common to both widths
  // -------------------------------------------------------------------
  task run_common;
    begin
      step = 1; // reset values
      rdx(A_DOUT, 32'd0); rdx(A_DIR, 32'd0); rdx(A_DIN, 32'd0);
      rdx(A_RISE, 32'd0); rdx(A_FALL, 32'd0); rdx(A_HIGH, 32'd0);
      rdx(A_LOW, 32'd0);  rdx(A_EN, 32'd0);   rdx(A_ST, 32'd0);
      check32(out_w, 32'd0); check32(oe_w, 32'd0); check1(irq_w, 1'b0);

      step = 2; // read/write registers, partial strobes, bits above N
      rw_lanes(A_DOUT);
      rw_lanes(A_DIR);
      rw_lanes(A_RISE);
      rw_lanes(A_FALL);
      rw_lanes(A_HIGH);
      rw_lanes(A_LOW);

      step = 3; // low-level enables with pins low set status, masked: no irq
      rdx(A_ST, pins_mask);
      check1(irq_w, 1'b0);
      wrf(A_ST, 32'hFFFF_FFFF);
      rdx(A_ST, 32'd0);

      step = 4;
      rw_lanes(A_EN);
      check1(irq_w, 1'b0);

      step = 5; // gpio_out and gpio_oe follow DATA_OUT and DIR
      wrf(A_DOUT, 32'hDEAD_BEEF);
      check32(out_w, 32'hDEAD_BEEF & pins_mask);
      check32(oe_w, 32'd0);
      wrf(A_DIR, 32'h1234_5678);
      check32(oe_w, 32'h1234_5678 & pins_mask);
      check32(out_w, 32'hDEAD_BEEF & pins_mask);
      wr(A_DOUT, 32'h0000_0000, 4'b0001, 1'b0);
      check32(out_w, 32'hDEAD_BE00 & pins_mask);
      rdx(A_DOUT, 32'hDEAD_BE00 & pins_mask);
      rdx(A_DIR, 32'h1234_5678 & pins_mask);
      wrf(A_DOUT, 32'd0);
      wrf(A_DIR, 32'd0);
      check32(out_w, 32'd0);
      check32(oe_w, 32'd0);

      step = 6; // DATA_IN sampling, read only
      set_pins(32'hC3A5_5AA5);
      rdx(A_DIN, 32'hC3A5_5AA5 & pins_mask);
      wr(A_DIN, 32'hFFFF_FFFF, 4'b1111, 1'b1);
      rdx(A_DIN, 32'hC3A5_5AA5 & pins_mask);
      wr(A_DIN, 32'h0000_0000, 4'b1111, 1'b1);
      set_pins(32'h0F0F_0F0F);
      rdx(A_DIN, 32'h0F0F_0F0F & pins_mask);
      set_pins(32'h0000_0000);
      cycles(2);
      rdx(A_DIN, 32'd0);

      step = 7; // PSLVERR policy and unmapped addresses
      wrf(A_DOUT, 32'h0000_003C);
      wrf(A_DIR, 32'h0000_0000);
      rd(8'h24, 32'd0, 1'b1); rd(8'h28, 32'd0, 1'b1); rd(8'h3C, 32'd0, 1'b1);
      rd(8'h40, 32'd0, 1'b1); rd(8'h44, 32'd0, 1'b1); rd(8'h60, 32'd0, 1'b1);
      rd(8'h80, 32'd0, 1'b1); rd(8'hFC, 32'd0, 1'b1); rd(8'h01, 32'd0, 1'b1);
      rd(8'h02, 32'd0, 1'b1); rd(8'h03, 32'd0, 1'b1); rd(8'h21, 32'd0, 1'b1);
      rd(8'h0A, 32'd0, 1'b1);
      wr(8'h01, 32'hFFFF_FFFF, 4'b1111, 1'b1);
      wr(8'h02, 32'hFFFF_FFFF, 4'b1111, 1'b1);
      wr(8'h03, 32'hFFFF_FFFF, 4'b1111, 1'b1);
      wr(8'h40, 32'hFFFF_FFFF, 4'b1111, 1'b1);
      wr(8'h80, 32'hFFFF_FFFF, 4'b1111, 1'b1);
      wr(8'hC0, 32'hFFFF_FFFF, 4'b1111, 1'b1);
      wr(8'h44, 32'hFFFF_FFFF, 4'b1111, 1'b1);
      wr(8'h4C, 32'hFFFF_FFFF, 4'b1111, 1'b1);
      wr(8'h8C, 32'hFFFF_FFFF, 4'b1111, 1'b1);
      wr(8'h24, 32'hFFFF_FFFF, 4'b1111, 1'b1);
      wr(8'h3C, 32'hFFFF_FFFF, 4'b1111, 1'b1);
      rdx(A_DOUT, 32'h0000_003C);
      rdx(A_DIR, 32'd0);
      rdx(A_RISE, 32'd0);
      rdx(A_ST, 32'd0);
      check32(out_w, 32'h0000_003C);
      wr(A_DOUT, 32'hFFFF_FFFF, 4'b0000, 1'b0);
      rdx(A_DOUT, 32'h0000_003C);
      wrf(A_DOUT, 32'd0);
    end
  endtask

  // -------------------------------------------------------------------
  // Detection at N = 8
  // -------------------------------------------------------------------
  task det_n8;
    begin
      step = 20; // rising edge fires once
      wrf(A_RISE, 32'h01);
      set_pins(32'h01); cycles(2); rdx(A_ST, 32'h01);
      wrf(A_ST, 32'h01); rdx(A_ST, 32'h00);
      cycles(3); rdx(A_ST, 32'h00);
      set_pins(32'h00); cycles(2); rdx(A_ST, 32'h00);

      step = 21; // one-cycle pulse
      wrf(A_RISE, 32'h02);
      set_pins(32'h02); cycles(1); set_pins(32'h00); cycles(2);
      rdx(A_ST, 32'h02);
      wrf(A_ST, 32'h02); rdx(A_ST, 32'h00);

      step = 22; // falling edge
      wrf(A_RISE, 32'h00); wrf(A_FALL, 32'h04);
      set_pins(32'h04); cycles(2); rdx(A_ST, 32'h00);
      set_pins(32'h00); cycles(2); rdx(A_ST, 32'h04);
      wrf(A_ST, 32'h04); rdx(A_ST, 32'h00);

      step = 23; // both edges on one pin
      wrf(A_RISE, 32'h08); wrf(A_FALL, 32'h08);
      set_pins(32'h08); cycles(2); rdx(A_ST, 32'h08);
      wrf(A_ST, 32'h08); rdx(A_ST, 32'h00);
      set_pins(32'h00); cycles(2); rdx(A_ST, 32'h08);
      wrf(A_ST, 32'h08); rdx(A_ST, 32'h00);
      wrf(A_RISE, 32'h00); wrf(A_FALL, 32'h00);

      step = 24; // high level sets again after a clear
      wrf(A_HIGH, 32'h10);
      set_pins(32'h10); cycles(2); rdx(A_ST, 32'h10);
      wrf(A_ST, 32'h10); rdx(A_ST, 32'h10);
      set_pins(32'h00); cycles(2); rdx(A_ST, 32'h10);
      wrf(A_ST, 32'h10); rdx(A_ST, 32'h00);
      wrf(A_HIGH, 32'h00);

      step = 25; // low level
      wrf(A_LOW, 32'h20); cycles(2); rdx(A_ST, 32'h20);
      wrf(A_ST, 32'h20); rdx(A_ST, 32'h20);
      set_pins(32'h20); cycles(2);
      wrf(A_ST, 32'h20); rdx(A_ST, 32'h00);
      wrf(A_LOW, 32'h00); set_pins(32'h00); cycles(2); rdx(A_ST, 32'h00);

      step = 26; // several pending, clear some only
      wrf(A_RISE, 32'h8B);
      set_pins(32'h8B); cycles(2); rdx(A_ST, 32'h8B);
      check1(irq_w, 1'b0);
      wrf(A_ST, 32'h02); rdx(A_ST, 32'h89);
      wr(A_ST, 32'hFFFF_FFFF, 4'b1110, 1'b0); rdx(A_ST, 32'h89);
      wrf(A_ST, 32'h00); rdx(A_ST, 32'h89);

      step = 27; // interrupt mask
      check1(irq_w, 1'b0);
      wrf(A_EN, 32'h01); check1(irq_w, 1'b1);
      wrf(A_EN, 32'h02); check1(irq_w, 1'b0);
      wrf(A_EN, 32'h80); check1(irq_w, 1'b1);
      wrf(A_ST, 32'h80); check1(irq_w, 1'b0); rdx(A_ST, 32'h09);
      wrf(A_EN, 32'hFF); check1(irq_w, 1'b1);
      wrf(A_ST, 32'h09); check1(irq_w, 1'b0); rdx(A_ST, 32'h00);
      set_pins(32'h00); cycles(2);

      step = 28; // detection beats a clear on the same edge
      set_pins(32'h03); cycles(2); rdx(A_ST, 32'h03); check1(irq_w, 1'b1);
      set_pins(32'h00); cycles(2); rdx(A_ST, 32'h03);
      set_pins(32'h01);
      wrf(A_ST, 32'h03);
      rdx(A_ST, 32'h01); check1(irq_w, 1'b1);
      wrf(A_ST, 32'h01); rdx(A_ST, 32'h00); check1(irq_w, 1'b0);
      set_pins(32'h00);
      wrf(A_RISE, 32'h00); wrf(A_EN, 32'h00);
      cycles(2); rdx(A_ST, 32'h00);
    end
  endtask

  // -------------------------------------------------------------------
  // Detection at N = 32 (upper lanes)
  // -------------------------------------------------------------------
  task det_n32;
    begin
      step = 40; // rising edge on pin 31, strobed clears
      wrf(A_RISE, 32'h8000_0000); wrf(A_EN, 32'h8000_0000);
      set_pins(32'h8000_0000); cycles(2);
      rdx(A_ST, 32'h8000_0000); check1(irq_w, 1'b1);
      wr(A_ST, 32'hFFFF_FFFF, 4'b0111, 1'b0);
      rdx(A_ST, 32'h8000_0000); check1(irq_w, 1'b1);
      wr(A_ST, 32'h8000_0000, 4'b1000, 1'b0);
      rdx(A_ST, 32'h0000_0000); check1(irq_w, 1'b0);

      step = 41; // high level on pin 24, masked then unmasked
      wrf(A_HIGH, 32'h0100_0000);
      set_pins(32'h8100_0000); cycles(2);
      rdx(A_ST, 32'h0100_0000); check1(irq_w, 1'b0);
      wrf(A_ST, 32'h0100_0000); rdx(A_ST, 32'h0100_0000);
      wrf(A_EN, 32'h0100_0000); check1(irq_w, 1'b1);
      set_pins(32'h0000_0000); cycles(2);
      wr(A_ST, 32'h0100_0000, 4'b1000, 1'b0);
      rdx(A_ST, 32'h0000_0000); check1(irq_w, 1'b0);

      step = 42; // falling edge on pin 16, low level on pin 8
      wrf(A_HIGH, 32'd0); wrf(A_RISE, 32'd0); wrf(A_FALL, 32'h0001_0000);
      set_pins(32'h0001_0000); cycles(2); rdx(A_ST, 32'd0);
      set_pins(32'h0000_0000); cycles(2); rdx(A_ST, 32'h0001_0000);
      wrf(A_ST, 32'h0001_0000); rdx(A_ST, 32'd0);
      wrf(A_FALL, 32'd0); wrf(A_LOW, 32'h0000_0100); cycles(2);
      rdx(A_ST, 32'h0000_0100);
      wrf(A_LOW, 32'd0); wrf(A_ST, 32'h0000_0100); rdx(A_ST, 32'd0);
      wrf(A_EN, 32'd0);
    end
  endtask

  // -------------------------------------------------------------------
  // Reset again, with state and a pending interrupt
  // -------------------------------------------------------------------
  task reset_again;
    begin
      step = 50;
      wrf(A_DOUT, 32'h0000_005A); wrf(A_DIR, 32'h0000_003C);
      wrf(A_EN, 32'hFFFF_FFFF);   wrf(A_HIGH, 32'h0000_0001);
      wrf(A_RISE, 32'h0000_0002); wrf(A_FALL, 32'h0000_0004);
      set_pins(32'h0000_0001); cycles(2);
      rdx(A_ST, 32'h0000_0001); check1(irq_w, 1'b1);
      check32(out_w, 32'h0000_005A); check32(oe_w, 32'h0000_003C);
      do_reset;
      step = 51;
      check1(irq_w, 1'b0);
      rdx(A_DOUT, 32'd0); rdx(A_DIR, 32'd0); rdx(A_DIN, 32'h0000_0001);
      rdx(A_RISE, 32'd0); rdx(A_FALL, 32'd0); rdx(A_HIGH, 32'd0);
      rdx(A_LOW, 32'd0);  rdx(A_EN, 32'd0);   rdx(A_ST, 32'd0);
      check1(irq_w, 1'b0);
      set_pins(32'h0000_0000); cycles(2); rdx(A_ST, 32'd0);
    end
  endtask

  // -------------------------------------------------------------------
  // Main
  // -------------------------------------------------------------------
  initial begin
    passed    = 0;
    failed    = 0;
    step      = 0;
    cur       = 1'b0;
    presetn   = 1'b0;
    psel      = 1'b0;
    penable   = 1'b0;
    pwrite    = 1'b0;
    paddr     = 8'h00;
    pwdata    = 32'd0;
    pstrb     = 4'b0000;
    gpio_in8  = 8'h00;
    gpio_in32 = 32'd0;
    nonce     = 512'd0;

    @(negedge pclk);
    do_reset;

    cur = 1'b0;
    run_common;
    det_n8;
    reset_again;

    cur = 1'b1;
    run_common;
    det_n32;
    reset_again;

    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 512'd0;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule
